// tr — Türkçe.
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **sen**, nunca *siz*. É a mesma escolha do du, do ты, do tu, do je e do 你 — e no turco ela
// aparece na terminação de cada verbo, então não dá para ficar em cima do muro: é "seç" e não
// "seçin", "yaz" e não "yazın". Um app de amigos que conjuga no "siz" soa como carta de banco.
//
// VOCABULÁRIO, decidido uma vez: comunidade = topluluk, canal = kanal, sala de voz = ses odası,
// mensagem = mesaj, senha = şifre, transmissão = yayın, lixeira = çöp kutusu, tópico = konu,
// insígnia = rozet, selo = mühür.

