  'Administradores podem apagar mensagens de qualquer pessoa, gerenciar todos os canais, emojis e sons desta comunidade e remover membros. Só o dono dá e tira esse cargo.': 'Yöneticiler herkesin mesajını silebilir, bu topluluğun bütün kanallarını, emojilerini ve seslerini yönetebilir ve üye çıkarabilir. Bu yetkiyi yalnızca sahibi verir ve alır.',
