  'Como dono, você escolhe quem administra e pode remover qualquer pessoa.': 'Sahibi olarak kimin yöneteceğini sen seçersin ve istediğini çıkarabilirsin.',
  'Confete, fogos e corações que qualquer pessoa da sala pode mandar. Desligue se o seu computador engasgar durante a chamada — desligado, você não vê nem manda.': 'Odadaki herkesin gönderebileceği konfeti, havai fişek ve kalpler. Görüşme sırasında bilgisayarın zorlanıyorsa kapat — kapalıyken ne görürsün ne gönderirsin.',
