  'Veja se o microfone está captando a sua voz.': 'Mikrofonun sesini alıyor mu bir bak.',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': 'Henüz hiç yok. Hediye ya da ödül olarak gelirler — örneğin senin bir fikrin Syden’a girdiğinde.',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'Dışarıdan bir servisle girdin ve bu hesapta henüz şifren yok. Buradan bir tane belirle: ikinci bir giriş yolu olur, ve o servisi sonradan kapatmana izin veren şey de budur.',
  'Você perde o acesso aos canais desta comunidade. Para voltar, vai precisar de um convite novo.': 'Bu topluluğun kanallarına erişimini kaybedersin. Geri dönmek için yeni bir davet gerekir.',
