  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'Aşağıdaki kilometre taşları tek başına ulaşılamayacak şekilde seçildi — her biri birden çok kişiyi ve zaman ister.',
