  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.': 'Kapalıyken odadaki birinin yayını davet olarak görünür ve ancak İzle’ye bastığında inmeye başlar. Bu interneti ve işlemciyi korur — özellikle kalabalık odada.',
