  'Monstros de fantasia': 'Fantastik canavarlar',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'Gizli bir canavar seçilir, herkes listeden başka canavarlar tahmin eder. Her tahmin gizli olanla neyin eşleştiğini gösterir: tür, boyut, seviye, yönelim ve nasıl hareket ettiği. Daha az tahminle bilen daha çok puan alır.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'Mitolojiden gizli bir figür seçilir, herkes başkalarını tahmin eder. Her tahmin gizli olanla neyin eşleştiğini gösterir: mitoloji, tür, biçim ve neye hükmettiği. Daha az tahminle bilen daha çok puan alır.',
