  'Acerte os corvos que passarem. No coelhinho, não!': 'Geçen kargaları vur. Tavşancığı değil!',
  'Brasas da fogueira': 'Kamp Ateşi Közleri',
  'Desvie das brasas. São só três corações!': 'Közlerden kaç. Sadece üç kalp var!',
  'Cabo de guerra': 'Halat Çekme',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Halatı çekmek için çıkan oka bas. Hata yapınca takılırsın!',
  'Canteiro que encolhe': 'Küçülen Tarh',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Diğerlerini tarhın dışına it. Yanıp sönen kenar düşecek!',
  'Corrida de cavalinho': 'Tahta At Yarışı',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': '← ve → tuşlarını ritimle değiştir. Fazla acele edersen nefesin tükenir.',
  'Cartas do celeiro': 'Ambar Kartları',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'Sıran gelince bir kart aç ya da havuçları sakla. Tilki hepsini alır!',
  'Chuva de cenouras': 'Havuç Yağmuru',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Havuçları toplayarak aşağı in. Taşlardan kaç!',
  'De galho em galho': 'Daldan Dala',
  'Solte o cipó quando ele estiver na faixa clara.': 'Sarmaşığı açık renkli şeritteyken bırak.',
  'Colheita em dupla': 'İkili Hasat',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'İkili: dalda olan olgun çilekleri düşürür, aşağıdaki sepetle yakalar.',
  'Baile da toca': 'Yuva Balosu',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Dansın sırasını aklında tut. Sonunda işaretli lambada kimin dans ettiğini söyle.',
  'Chão que desmorona': 'Çöken Zemin',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'Biri üstünde durunca tahta çatlar. Yürümeye devam et ve diğerlerini suya it!',
  'Arrume a despensa': 'Kileri Topla',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Her kavanozun nerede durduğunu aklında tut ve hepsini yerine koy.',
  'Esconde-esconde na horta': 'Bostanda Saklambaç',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Fenerin bakmayacağı yere saklan. Fener kimdeyse o arar!',
  'Três flechas': 'Üç Ok',
  'A flecha sobe reta e fura o que encontrar. Os balões pequenos valem mais.': 'Ok dümdüz yükselir ve önüne çıkanı deler. Küçük balonlar daha çok değer.',
  'Bate quando der a flor': 'Çiçeği Görünce Vur',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Çerçevedekiyle aynı çiçek çıkınca vur. Yanlış resimde oyun dışısın.',
  'Foguete de cenoura': 'Havuç Roketi',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Halka yanınca pompala. Ritim dışında hava kaçar.',
  'Pegue a galinha': 'Tavuğu Yakala',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Tavuğu köşeye sıkıştır. Yorulunca yavaşlar.',
  'Repolhos no gelo': 'Buzda Lahanalar',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Buzdaki havuçları topla, lahanalardan kaç.',
  'Abóboras ladeira abaixo': 'Yokuş Aşağı Balkabakları',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Yukarıdan balkabakları yuvarlanıyor; tırmanan, onlardan kaçmak için şerit değiştirir!',
  'Quem está atrás da turma?': 'Kalabalığın Arkasında Kim Var?',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Kimin saklandığını bul. Tek şansın var: ne kadar erken, o kadar çok değer.',
  'Arremesso do nabo': 'Şalgam Fırlatma',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Şalgam sahaya dönünce bırak. Ne kadar hızlı dönerse o kadar uzağa gider.',
  'Onda no açude': 'Gölette Dalga',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': 'Kürekteki dalga gönderir; saldaki tam zamanında zıplar!',
  'Pula o ponteiro': 'Akrebin Üstünden Atla',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'Akrep geçerken zıpla. Gittikçe hızlanır.',
  'Ponte do riacho': 'Dere Köprüsü',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'Üç tahtayı köprüye kadar taşı. Batan taşlara dikkat!',
  'Quem está em qual toca?': 'Kim Hangi Yuvada?',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Hayvanları yuvadan yuvaya takip et. Sonunda balondakinin nerede olduğunu göster.',
  'As chaves da porteira': 'Kapının Anahtarları',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Altın bir havuç al ve kapıya götür. Biri eksik: taşıyanı it!',
  'Destampe os potes': 'Kavanozları Aç',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Her kapağı hızla okun yönüne çevir. Yanlış yön kapağı yeniden sıkar.',
  'Praga na toca': 'Yuvada Haşere',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Yuvalardan çıkan tırtıllara vur. Tavşancığa değil!',
  'Rebater o rabanete': 'Turpu Karşıla',
  'Rebata quando o rabanete chegar à base. Bem na hora, vai mais longe.': 'Turp kaleye gelince vur. Tam zamanında vurursan daha uzağa gider.',
  'Regar a horta': 'Bostanı Sula',
  'Leve a nuvem até o canteiro com sede.': 'Bulutu susamış tarha götür.',
