  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Rampalar, şato ve yel değirmeniyle 3D sekiz delik; herkes aynı anda aynı deliği oynar. Nişan almak ve güç vermek için sürükle, sonra bırak. Toplamda en az vuruşu yapan kazanır.',
  'Ver o buraco de cima': 'Deliğe yukarıdan bak',
  'Fora da pista! Mais uma tacada.': 'Pistin dışında! Bir vuruş daha.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Nişan almak için yana, güç için aşağı sürükle ve bırak. Klavyede: yön tuşları nişan alır, basılı tutulan Boşluk gücü verir.',
  'Futebol dos coelhos': 'Tavşan Futbolu',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Küçük sahada futbol, yukarıdan görünüm. Topu sürmek için ona dokun, daha sert şut için Boşluğu basılı tut ve X ile pas ver. Odada takımlar botlarla tamamlanır.',
