  'Caça às pragas da horta': 'Bostan Haşere Avı',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Kargalar ve çekirgeler bostana saldırıyor. Kaçmadan önce vurmak için nişan al ve tıkla: cephane sayılı ve her dalga daha hızlı geliyor. En çok puanı toplayan kazanır.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Haşereler kaçmadan önce nişan al ve tıkla. Her atış bir havuç harcar.',
