  'Comprar': 'Satın al',
  '{nome} chegou à cenoura dourada.': '{nome} altın havuca ulaştı.',
  'Quantas rodadas?': 'Kaç tur?',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Tavşanlar bostanı tilkilerden, kargalardan ve bir porsuktan koruyor. Birlikte yürüyün, kombo vurun ve birbirinizi kollayın: 1 ila 4 kişi.',
  'Pulo do coelho': 'Tavşan Zıplaması',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Bir platform yarışı: koş, zıpla ve düşme. Tek başına, zamana ve arkadaşlarının hayaletlerine karşı; ekiple, canlı, tek bölümde ya da üçünde birden.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Yan yana iki sebzenin yerini değiştirerek üç ya da daha fazla aynısını birleştir. Yığın durmadan yükselir: tepeye ulaşmasına izin verme. Ekiple, zincirler ve kombolar diğerlerine kasa gönderir.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Altı delikli minigolf, herkes aynı deliği aynı anda oynar. Vurmak için topu geriye çek ve bırak. Toplamda en az vuruşu yapan kazanır.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Herkes sırası gelince zar atar ve bostanda ilerler. Altın havucu satın almak için havuç topla; her turdan sonra ekip bir mini oyun oynar. En çok altın havucu olan kazanır.',
