  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.':
    'Brezilya’nın başkentlerinde dolaş, şehir satın al ve üzerinde duranlardan kira topla. Bir bölgenin tamamı sende olunca bina dikebilirsin. Takas yap, açık artırmalarda yarış ve parasız kalma.',
