  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Bildiğin domino, 2–4 kişiyle (4 kişiyle eşli). Taşları uçlara ekle, ilk biten diğerlerinin elindeki puanları alır.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Paulista truco: açık kart ve kozlarla, 2 kişi ya da 4 kişi eşli. Truco iste, altıya, dokuza ve on ikiye çıkar ya da kaç. 12 puana ulaşan kazanır.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Brezilya daması: taş almak zorunlu, ileri ve geri, dama da tüm çaprazı gider. Oda izler.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Herkes filosunu saklar ve diğerinin denizine ateş eder. Vurursan bir daha atarsın. Tüm filoyu ilk batıran kazanır. Oda izler.',
