  'Cozinha da toca': 'Yuvanın mutfağı',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Kasalardan malzemeleri al, tahtada doğra, yakmadan ocakta ve fırında pişir, tabağa diz ve pencereden teslim et. Herkes aynı siparişleri alır: 3 dakikada en çok tabak teslim eden kazanır.',
