  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Bilgisayarında yapılan ses ve kamera efektleri, sunucuya hiçbir şey göndermeden.",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Yuva Zindanı",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Mantar kralının yuvasından birlikte geçin: yaratıklarla dolu odalar, gidip gelen havuçlu bir sandık, aynı anda iki kişi isteyen düğmeler ve kilitli kapı. 1 ile 4 kişi arası.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Yuva Ringi",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Bilgisayarın üç rakibine karşı refleks boksu. Her yumruğun işaretini oku, kaç ya da blokla ve boşluğa vur. Eldiven parladığında vurmak güçlü yumruğun yıldızını doldurur.",
  'Esquivar': "Kaç",
  'Abaixar e defender': "Eğil ve blokla",
  'Socar': "Vur",
  'Soco forte': "Güçlü yumruk",
  'Aperte os socos para levantar!': "Kalkmak için yumruk tuşlarına bas!",
  'Lutas vencidas: {n}': "Kazanılan maçlar: {n}",
  'Nocaute!': "Nakavt!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Yıldız Rotası",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Uzay gemilerindeki tavşanlar bir gezegenin yüzeyinin üstünde ve uzayda: ateş et, hedefe kilitlenmek için ateşi basılı tut, mermileri savuşturmak için dön ve çatalda yolunu seç. Ekip aynı rotada uçar, sonda da patron bekler.",
  'Pirueta': "Dönüş",
  'Segure para travar a mira': "Kilitlenmek için basılı tut",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Havuç Komandosu",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Ekiple koş ve ateş et: havuçatar sekiz yöne nişan alır, el bombası yolu açar, kafesteki yavru tavşanları kurtaran güçlendirme kazanır. Sonda ejderha bekliyor: 1 ila 4 kişi.",
  'Andar e mirar': "Yürü ve nişan al",
  'Granada': "El bombası",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Bostan Pinbolu",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Sebze bahçesinde bir pinbol masası: yayı tut, lahanalardan sek ve tavşanın yuvasını yakmak için üç havucu devir; yuva bir top daha bırakır. Üç top var, fazla sallamak masayı kilitler.",
