  "A largada precisa de uma reta.": "Başlangıç için düz bir parça gerekiyor.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "{nome} oyuncusunun Harikası 2 dakika ayakta kaldı.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "Aynı konum üçüncü kez gelirse berabere, sadece damayla yeme olmadan 20 hamle de öyle.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "Gece, kurt adamların kime saldırdığını gör. Bir iksir o kişiyi kurtarır, diğeri birini oyundan çıkarır; her biri bir kez kullanılır.",
