  "Vocês derrubaram os dois centros da vila da outra equipe.": "Diğer takımın iki köy merkezini de yıktınız.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "Kimsenin almadığı şehir açık artırmaya çıkar. Bir şehri ipotek etmek para kazandırır ama o şehir kira toplamaz.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "İpucu oynayacak taşı yakar. İpucu alınan bulmaca puan getirmez; yarışta ipucu 10 saniye götürür.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Koz, açık karttan sonraki değerdir ve hepsini yener. Kendi aralarında: karo, maça, kupa ve sinek, yani zap.",
  "A última nave de cada volta sai.": "Her turun son gemisi elenir.",
  "Abaixar": "Eğil",
  "Acertos em sequência: {n}": "Art arda çözülen: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Zarla ilerle ve durduğun başkenti satın al. Başkasının şehrinde duran kira öder.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Her satır, sütun ve 3 × 3 blokta 1'den 9'a kadar sayılar tekrar etmeden bulunur.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Herkese 3 kart dağıtılır. 3 turdan 2'sini kazanan eli alır.",
  "Campeonato": "Şampiyona",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "11 puanda eşler kartlara bakar ve on bir elini oynayıp oynamayacağına karar verir. 12'ye ulaşan kazanır.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Bölgenin tamamı sendeyse 4 binaya kadar inşa et: her biriyle kira artar.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Güçlü yumruk (★) bütün yıldızları bir anda harcar ve daha çok acıtır.",
  "Dica": "İpucu",
  "Dica: este problema não pontua": "İpucu: bu bulmaca puan getirmez",
  "Dica: tira 10 segundos": "İpucu: 10 saniye eksi",
  "Eliminação": "Eleme",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Masanın bir ucuna aynı sayıyı taşıyan bir taş ekle.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Önce kareyi, sonra sayıyı seç. Kalem notlarını sadece sen görürsün.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Darbeden kaç ve hemen ardından vur: bu karşı saldırıdır ve yıldız kazandırır.",
  "Fora da corrida na volta {n}.": "{n}. turda yarış dışı.",
  "Força das cartas": "Kartların gücü",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Turların sonunda en büyük servete sahip olan ya da son kalan kazanır.",
  "Iniciante": "Acemi",
  "Mestre": "Usta",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "Seride her doğru daha zor bir bulmaca getirir, ilk hata da seriyi bitirir.",
  "O número pequeno no botão diz quantos ainda faltam.": "Düğmedeki küçük sayı daha kaç tane kaldığını gösterir.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "Bilgisayara karşı art arda beş pist, puanlı.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Truco iste, el 3 değerinde olur. Cevap veren kabul eder, kaçar ya da 6, 9 veya 12'ye çıkarır.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Bitiren taşsız kalır ve diğerlerinin elindeki puanları alır. Oyun kilitlenirse elinde en az puan olan alır.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Uyan taş yoksa taş çek. Çekecek taş da yoksa sıra geçer.",
  "Sequência": "Seri",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Eldiven parladığında vur: darbe durur ve bir yıldız kazanırsın.",
  "Treino livre": "Serbest antrenman",
