  "Saara": "Sahra",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Gizli bir hayvan seçilir ve herkes tahmin eder. Her tahmin gizliyle neyin eşleştiğini gösterir: sınıf, beslenme, yaşadığı yer ve ağırlık. Daha az tahminle bulan daha çok puan alır.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "Gizli bir dinozor seçilir ve herkes tahmin eder. Her tahmin gizliyle neyin eşleştiğini gösterir: dönem, beslenme, grup, uzunluk ve bulunduğu yer. Daha az tahminle bulan daha çok puan alır.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Gizli bir kimyasal element seçilir ve herkes tahmin eder. Her tahmin gizliyle neyin eşleştiğini gösterir: aile, fiziksel hâl, periyot, grup ve atom numarası. Daha az tahminle bulan daha çok puan alır.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "Brezilya'dan gizli bir eyalet seçilir ve herkes tahmin eder. Her tahmin gizliye olan uzaklığı ve yönü, bölgeyi, nüfusu, yüzölçümünü, kıyıyı ve başka ülkeyle sınırı gösterir. Daha az tahminle bulan daha çok puan alır.",
